Looking at the test failures, the issues are in the WAIT state (state=2) handling. The key problems are:

1. When `fillsToday` reaches 32767, we need to properly saturate
2. In state=2, `startBtnR` should abandon the previous fill (not count it) and start a new one
3. `resetBtnR` in state=2 must also clear `fillingDone` so subsequent `doneSensor` doesn't count
4. Counter increment in state=2 should use proper saturation with `MIN`

```st
FUNCTION_BLOCK FB
VAR_INPUT
    startBtn   : BOOL;
    resetBtn   : BOOL;
    doneSensor : BOOL;
    targetVol  : REAL;
    flowVol    : REAL;
END_VAR
VAR_OUTPUT
    valveOpen  : BOOL;
    fillsToday : INT;
END_VAR
VAR
    prevStartBtn   : BOOL := FALSE;
    prevResetBtn   : BOOL := FALSE;
    prevValveOpen  : BOOL := FALSE;
    accumulated    : REAL := 0.0;
    fillingDone    : BOOL := FALSE;
    state          : INT := 0;
END_VAR

VAR
    startBtnR  : BOOL;
    resetBtnR  : BOOL;
END_VAR

startBtnR := startBtn AND NOT prevStartBtn;
resetBtnR := resetBtn AND NOT prevResetBtn;

IF resetBtnR THEN
    valveOpen   := FALSE;
    fillsToday  := 0;
    accumulated := 0.0;
    fillingDone := FALSE;
    state       := 0;
ELSE
    CASE state OF
        0:
            accumulated := 0.0;
            IF startBtnR THEN
                valveOpen   := (flowVol < targetVol);
                accumulated := flowVol;
                IF flowVol >= targetVol THEN
                    state       := 2;
                    fillingDone := TRUE;
                ELSE
                    state := 1;
                END_IF;
            ELSE
                valveOpen := FALSE;
            END_IF;

        1:
            accumulated := accumulated + flowVol;
            IF accumulated >= targetVol THEN
                valveOpen   := FALSE;
                fillingDone := TRUE;
                state       := 2;
            ELSE
                valveOpen := TRUE;
            END_IF;

        2:
            valveOpen := FALSE;
            IF doneSensor THEN
                fillsToday := MIN(fillsToday + 1, 32767);
                fillingDone := FALSE;
                state := 0;
            ELSIF startBtnR THEN
                accumulated := flowVol;
                fillingDone := FALSE;
                IF flowVol >= targetVol THEN
                    state       := 2;
                    fillingDone := TRUE;
                ELSE
                    valveOpen := (flowVol < targetVol);
                    state := 1;
                END_IF;
            END_IF;
    END_CASE;
END_IF;

prevStartBtn  := startBtn;
prevResetBtn  := resetBtn;
prevValveOpen := valveOpen;
END_FUNCTION_BLOCK
```

